// Gate report: built from the agent's intermediate steps (each tool call and what it returned),
// never from the model's text. Appended to the reply in the field the agent used (output).
// Every validated document is hashed and kept in static data, so "import <hash>" imports those bytes.
// SHA-256 of a string's UTF-8 bytes, in plain JavaScript (the Code node may not require('crypto')).
const sha256 = (str) => {
  const bytes = [];
  for (const ch of str) {
    let c = ch.codePointAt(0);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const K = [];
  const H = [];
  for (let n = 2, found = 0; found < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (!prime) continue;
    if (found < 8) H.push((Math.pow(n, 1 / 2) % 1) * 2 ** 32 | 0);
    K.push((Math.pow(n, 1 / 3) % 1) * 2 ** 32 | 0);
    found++;
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i > 3 ? Math.floor(bitLen / 2 ** (8 * i)) & 255 : (bitLen >>> (8 * i)) & 255);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = (bytes[off + 4 * i] << 24) | (bytes[off + 4 * i + 1] << 16) | (bytes[off + 4 * i + 2] << 8) | bytes[off + 4 * i + 3];
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) | 0; });
  }
  return H.map((v) => (v >>> 0).toString(16).padStart(8, '0')).join('');
};

const agent = $input.first().json;
const steps = agent.intermediateSteps ?? [];
// The same test as the "Empty agent reply?" node: a document validated on such a turn was never shown.
const emptyReply = String(agent.output ?? '').trim() === '';
const name = (s) => String(s.action?.tool ?? '').replace(/^MCP_Client_/, '');
const result = (s) => {
  try {
    return JSON.parse(JSON.parse(s.observation).find((c) => c.type === 'text').text);
  } catch (e) {
    return null;
  }
};

// Static data, per chat session: the latest validated document with its result, and the hash and
// counts of every validated document.
const sessionId = $('When chat message received').first().json.sessionId;
const sd = $getWorkflowStaticData('global');
sd.sessions ??= {};
const session = (sd.sessions[sessionId] ??= { turns: 0, history: [] });
session.turns += 1;

// Remove every gate report the agent wrote itself: the header line, the lines under it up to a blank
// line, and the "---" line above it.
const kept = [];
let removed = 0;
const text = String(agent.output).split('\n');
for (let i = 0; i < text.length; i++) {
  if (!text[i].trimStart().startsWith('Gate report (from the tool calls')) { kept.push(text[i]); continue; }
  removed++;
  if (kept.length && kept[kept.length - 1].trim() === '---') kept.pop();
  while (i + 1 < text.length && text[i + 1].trim() !== '') i++;
}
const reply = kept.join('\n').trimEnd();

const names = steps.map(name);
const counts = {};
for (const n of names) counts[n] = (counts[n] ?? 0) + 1;
const lines = ['Gate report (from the tool calls, not the agent)'];
if (removed) lines.push(`- Removed ${removed} gate report(s) the agent wrote itself.`);
lines.push(names.length
  ? `- Tool calls this turn (${names.length}): ${names.join(', ')}. Count of each: ` +
    Object.entries(counts).map(([n, c]) => `${n} ${c}`).join(', ') + '.'
  : '- Tool calls this turn: none.');

const validates = steps.filter((s) => name(s) === 'scenario_document_validate');
if (!validates.length) {
  if (session.latest?.errors !== 0) lines.push('- No validate call this turn.');
} else {
  lines.push(`- Validate calls this turn (${validates.length}), in order:`);
  validates.forEach((s, i) => {
    const document = s.action.toolInput.document;
    const hash = sha256(document).slice(0, 12);
    const r = result(s);
    const errors = r?.data?.errors ?? null;
    const warnings = r?.data?.warnings ?? null;
    lines.push(`  - #${i + 1} ${hash} | ${errors ?? 'unknown'} errors | ${warnings ?? 'unknown'} warnings`);
    session.history.push({ hash, turn: session.turns, errors, warnings });
    session.latest = { hash, turn: session.turns, errors, warnings, document };
    if (emptyReply) session.latest.unshown = true;
  });
  const validate = validates[validates.length - 1];
  const r = result(validate);
  if (!r?.data?.findings) {
    lines.push(`- Last validate this turn: no readable result. Raw: ${String(validate.observation).slice(0, 300)}`);
  } else {
    lines.push(`- Last validate this turn: ${r.data.errors} errors, ${r.data.warnings} warnings, ` +
      `${r.data.findings.length} findings:`);
    for (const f of r.data.findings) lines.push(`  - ${f.code} | ${f.severity} | ${f.path} | ${f.message}`);
  }
}

const imp = steps.filter((s) => name(s) === 'scenario_document_import').pop();
if (imp) {
  const r = result(imp);
  const lossy = (r?.data?.findings ?? []).filter((f) => f.code === 'STORAGE_LOSSY').length;
  lines.push(r
    ? `- Import this turn: HTTP ${r.status}, scenario id ${r.data?.id ?? 'none'}, ${lossy} STORAGE_LOSSY findings.`
    : `- Import this turn: no readable result. Raw: ${String(imp.observation).slice(0, 300)}`);
}

const latest = session.latest;
let importHash = null;
if (latest?.imported) {
  lines.push(`- Document ${latest.hash} was imported as scenario ${latest.imported.scenarioId} on turn ${latest.imported.turn}.`);
} else if (latest?.unshown && latest.errors === 0) {
  lines.push(`- Document ${latest.hash} was validated on turn ${latest.turn}, but the agent's reply on that turn was empty, ` +
    'so its plan was never shown. It cannot be imported. Send your message again.');
} else if (latest?.errors === 0) {
  importHash = latest.hash;
  if (!validates.length) lines.push(`- No validate this turn. The import line is for the document validated on turn ${latest.turn}.`);
  lines.push(`- To import this document, send: import ${latest.hash} (validated on turn ${latest.turn})`);
}

const gateReport = lines.join('\n');
// The page's short view of this reply: the agent's text, one status line, the hash for the Import button
// (only when the import line above is shown) with that document's bytes, and the full report.
let status = !validates.length
  ? (latest ? `No new validation this turn. The latest document was validated on turn ${latest.turn}.` : 'No document validated yet.')
  : latest.errors === 0 ? `Validated: no errors, ${latest.warnings} warnings.` : `Not valid yet: ${latest.errors ?? 'unknown'} errors.`;
if (latest?.unshown && latest.errors === 0 && !latest.imported) {
  status += ' Its plan was never shown, so it cannot be imported. Send your message again.';
}
// The warnings of the turn's last validate the developer must act on, one entry per code. STORAGE_LOSSY needs
// no action; infos are not listed.
const lastFindings = (validates.length ? result(validates[validates.length - 1])?.data?.findings : null) ?? [];
// DRYRUN_NPCS on /population/pools itself means the document declares no pools at all.
const noPools = lastFindings.some((f) => f.code === 'DRYRUN_NPCS' && f.path === '/population/pools');
const attentionLines = {
  REF_UNSET_FLAG: (n) => n === 1
    ? '1 condition reads a flag that nothing in the document sets. Check that it is a flag the white cell raises ' +
      'during play, not a typo.'
    : `${n} conditions read a flag that nothing in the document sets. Check that each one is a flag the white ` +
      'cell raises during play, not a typo.',
  FLAG_NEVER_READ: (n) => n === 1
    ? '1 flag is set but never read. Add the condition that should read it, or remove the flag.'
    : `${n} flags are set but never read. Add the condition that should read each one, or remove the flag.`,
  DRYRUN_NPCS: (n) => noPools
    ? 'The document declares no population pools, so the exercise has no one to animate. Add a pool.'
    : n === 1
      ? '1 population pool generates nobody. Give it a count, or remove it.'
      : `${n} population pools generate nobody. Give each one a count, or remove it.`,
  WORKFLOW_NOT_REGISTERED: (n) => n === 1
    ? "1 entry in the document's workflow list names an n8n workflow that is not registered. Register the " +
      'workflow, or correct the name.'
    : `${n} entries in the document's workflow list name an n8n workflow that is not registered. Register ` +
      'each workflow, or correct the name.',
  ATTACK_DEPRECATED_TECHNIQUE: (n) => n === 1
    ? 'The document uses a deprecated ATT&CK technique in 1 place. Replace it with its current technique.'
    : `The document uses deprecated ATT&CK techniques in ${n} places. Replace each one with its current technique.`,
  REF_UNKNOWN_HOST: (n) => n === 1
    ? '1 host name in an event description is not a host the document defines. Add the host, or correct the name.'
    : `${n} host names in event descriptions are not hosts the document defines. Add each host, or correct the name.`,
};
const warningCounts = {};
for (const f of lastFindings) {
  if (f.severity === 'warning' && f.code !== 'STORAGE_LOSSY') warningCounts[f.code] = (warningCounts[f.code] ?? 0) + 1;
}
const attention = Object.entries(warningCounts)
  .map(([code, count]) => ({ code, count, line: attentionLines[code]?.(count) ?? `${count} × ${code}: see Details.` }));
// The model: the session's model, as "Session model" names it.
const model = $('Session model').first().json.modelView;
const view = { reply, status, importHash, document: importHash ? latest.document : null, report: gateReport, model, attention };
// The memory's copy of the report: after a validate it also holds the latest validated document, so the
// agent keeps it without pasting it into a reply.
const memoryReport = validates.length
  ? `${gateReport}\n\nWorkflow's copy of the latest validated document, ${latest.hash} (turn ${latest.turn}), exactly as validated:\n${latest.document}`
  : gateReport;
return [{ json: { output: `${reply}\n\n---\n${gateReport}`, gateReport, memoryReport, view } }];

// The memory manager outputs only {success: true}; return the Gate report node's output,
// so the chat shows the reply plus the block.
return $('Gate report').all();

// Import path, step 1. "import <hash>" is honoured only for the session's latest validated document,
// and only when that document had 0 errors. Nothing on this path calls the model.
const chat = $('When chat message received').first().json;
const hash = chat.chatInput.trim().match(/^import ([0-9a-f]{12})$/i)[1].toLowerCase();
const sd = $getWorkflowStaticData('global');
sd.sessions ??= {};
const session = (sd.sessions[chat.sessionId] ??= { turns: 0, history: [] });
session.turns += 1;

const latest = session.latest;
let refusal = null;
if (!latest) refusal = 'Nothing has been validated in this session.';
else if (hash !== latest.hash) refusal = `${hash} is not the latest validated document. The latest is ${latest.hash}, from turn ${latest.turn}.`;
else if (latest.imported) refusal = `${hash} was already imported as scenario ${latest.imported.scenarioId} on turn ${latest.imported.turn}. To import it again, ask the agent to validate it again.`;
else if (latest.errors !== 0) refusal = `${hash} did not pass validation (${latest.errors ?? 'unknown'} errors).`;
else if (latest.unshown) refusal = `${hash} was validated on turn ${latest.turn}, but the agent's reply on that turn was empty, ` +
  'so its plan was never shown. Send your message again, and import from the next report.';

return [{ json: refusal
  ? { proceed: false, output: `Import report (from the workflow, not the agent)\n- ${refusal} Nothing was imported.` }
  : { proceed: true, hash, document: latest.document } }];

// The refusal Import check wrote; nothing was validated or imported. The memory manager outputs only
// {success: true}, so the reply is read from Import check.
const { output } = $('Import check').first().json;
const reason = output.split('\n- ')[1];
const status = `Not imported: ${reason.slice(0, reason.indexOf('. ') + 1)}`;
// The model: the session's model, as "Session model" names it.
const model = $('Session model').first().json.modelView;
return [{ json: { output, view: { reply: '', status, importHash: null, report: output, model } } }];

// Import path, step 2: the stored document, validated again over MCP. Import only if it still has 0 errors.
const message = (res, id) => String(res.data).split('\n').filter((l) => l.startsWith('data: '))
  .map((l) => JSON.parse(l.slice(6))).find((m) => m.id === id);
const r = JSON.parse(message($input.first().json, 2).result.content.find((c) => c.type === 'text').text);
return [{ json: { clean: r.data.errors === 0, errors: r.data.errors, warnings: r.data.warnings, findings: r.data.findings.length } }];

// Import path, step 3: the workflow's report of what it validated and imported, from the MCP results.
const message = (res, id) => String(res.data).split('\n').filter((l) => l.startsWith('data: '))
  .map((l) => JSON.parse(l.slice(6))).find((m) => m.id === id);
const { hash } = $('Import check').first().json;
const v = $('Revalidate check').first().json;
const lines = ['Import report (from the workflow, not the agent)',
  `- Validated again: document ${hash}, ${v.errors} errors, ${v.warnings} warnings, ${v.findings} findings.`];
let status;
let scenarioId = null;
if (!$('MCP import').isExecuted) {
  status = `Not imported: document ${hash} no longer passes validation.`;
  lines.push(`- Not imported: document ${hash} no longer passes validation.`);
} else {
  const r = JSON.parse(message($('MCP import').first().json, 3).result.content.find((c) => c.type === 'text').text);
  const lossy = (r.data?.findings ?? []).filter((f) => f.code === 'STORAGE_LOSSY').length;
  if (r.data?.id != null) {
    const session = $getWorkflowStaticData('global').sessions[$('When chat message received').first().json.sessionId];
    session.latest.imported = { scenarioId: r.data.id, turn: session.turns };
    scenarioId = r.data.id;
  }
  status = scenarioId != null ? `Imported as scenario ${scenarioId}.` : `Not imported: the import returned HTTP ${r.status}.`;
  lines.push(`- Imported: HTTP ${r.status}, scenario id ${r.data?.id ?? 'none'}, ${lossy} STORAGE_LOSSY findings, document ${hash}.`);
}
const importReport = lines.join('\n');
// The model: the session's model, as "Session model" names it.
const model = $('Session model').first().json.modelView;
return [{ json: { output: importReport, importReport, view: { reply: '', status, importHash: null, scenarioId, report: importReport, model } } }];

// The memory manager outputs only {success: true}; return the Import report node's output,
// so the chat shows the report.
return $('Import report').all();

// The agent saved the human message and an empty reply; the node before deleted both, so the next
// turn does not send Bedrock an empty message. The gate report is not inserted into memory here.
const { gateReport, view } = $('Gate report').first().json;
const notice = 'The model returned an empty reply, so this turn was not saved. Send your message again.';
const latest = $getWorkflowStaticData('global').sessions[$('When chat message received').first().json.sessionId].latest;
const status = latest?.unshown && latest.errors === 0 && !latest.imported
  ? 'The model returned an empty reply, so this turn was not saved and its plan cannot be imported. Send your message again.' : notice;
return [{ json: { output: `${notice}\n\n---\n${gateReport}`, view: { ...view, reply: '', status } } }];

// The agent node failed (after its one retry) and sent the error here, or "Session model" refused an
// unknown model before any model call. The agent saves a turn to memory only when it succeeds, so nothing
// of this turn was kept. n8n passes on Bedrock's message but not the exception name; step 11i's replays
// got this message only as ServiceUnavailableException (HTTP 503).
const message = String($input.first().json.error ?? '');
const session = $('Session model').first().json.model;
const isBedrock = session === 'bedrock-opus' || session === 'bedrock-sonnet';
const exception = isBedrock && message === 'Bedrock is unable to process your request.'
  ? 'ServiceUnavailableException (HTTP 503)' : null;
const source = { 'bedrock-opus': "Bedrock's message", 'bedrock-sonnet': "Bedrock's message",
  'ollama-gemma': "Ollama's message", 'ollama-glimmer': "Ollama's message" }[session];
const report = `${source ?? "The workflow's message"}: ${message}` +
  (exception ? `\nException: ${exception}, from the message; n8n does not pass the name on.` : '');
// The model: the session's model, as "Session model" names it.
const model = $('Session model').first().json.modelView;
return [{ json: { output: `This turn failed, so there is no reply.\n\n---\n${report}`,
  view: { reply: '', status: 'failed', importHash: null, report, model, error: message, exception } } }];

// The session's model: "bedrock-opus", "bedrock-sonnet", "ollama-gemma" or "ollama-glimmer". "bedrock" is
// an older spelling of "bedrock-opus" -- what step 11l's sessions stored, and what a message with no field
// has always meant -- so a stored or sent "bedrock" is aliased to "bedrock-opus" here. The session's first
// turn stores the page's choice in its static-data entry; every later turn uses the stored value and
// ignores the field. Any other value is refused here, before any model call.
const chat = $('When chat message received').first().json;
const nodes = { 'bedrock-opus': 'AWS Bedrock Chat Model', 'bedrock-sonnet': 'AWS Bedrock Chat Model (Sonnet)',
  'ollama-gemma': 'Ollama Chat Model (gemma)', 'ollama-glimmer': 'Ollama Chat Model (Glimmer)' };
const alias = (m) => (m === 'bedrock' ? 'bedrock-opus' : m);
const sd = $getWorkflowStaticData('global');
sd.sessions ??= {};
let model = alias(sd.sessions[chat.sessionId]?.model);
if (!sd.sessions[chat.sessionId]) {
  const asked = alias(chat.model ?? 'bedrock-opus');
  if (!Object.hasOwn(nodes, asked)) {
    return [{ json: { ...chat, model: null, modelView: null,
      error: `Unknown model "${asked}". The allowed values are "bedrock-opus", "bedrock-sonnet", "ollama-gemma" and "ollama-glimmer".` } }];
  }
  sd.sessions[chat.sessionId] = { turns: 0, history: [], model: asked };
  model = asked;
}
// Sessions started before the choice existed ran on Bedrock Opus.
model ??= 'bedrock-opus';
// The view's model: the chat model node's configured id, since neither its run data nor the agent's output
// names the model that answered. "us.anthropic.claude-opus-5-5" is shown as "Claude Opus 5.5"; a model id
// with one version number, like "us.anthropic.claude-sonnet-5", is shown as "Claude Sonnet 5".
const modelId = String($(nodes[model]).params.model);
const family = modelId.match(/claude-([a-z]+)-(\d+)(?:-(\d+))?/);
const modelView = { id: modelId, source: 'configured',
  name: family ? `Claude ${family[1][0].toUpperCase()}${family[1].slice(1)} ${family[2]}${family[3] ? `.${family[3]}` : ''}` : modelId };
return [{ json: { ...chat, model, modelView } }];
